import VideoPlayer from '../../components/VideoPlayer/page.jsx';
import { log } from 'console';

async function getVideoData() {
  // Aqui você busca as URLs da sua API
  const res = await fetch('http://localhost:4000/api/v2/hianime/episode/sources?animeEpisodeId=my-hero-academia-322?ep=6211');
  const data = await res.json();

  return {
    videoUrl: data.sources.url,     // exemplo: https://cdn.site.com/video/playlist.m3u8
    subtitleUrl: data.tracks.filter((lingua) => lingua.lang = "Portuguese - Portuguese (Brasil)").url,   // exemplo: https://cdn.site.com/subs/legenda.vtt
  };
}

export default async function Page() {
  const { videoUrl, subtitleUrl } = await getVideoData();
  console.log({ videoUrl, subtitleUrl });
  return (
    <main className="flex justify-center items-center min-h-screen bg-black">
      <VideoPlayer src={videoUrl} subtitles={subtitleUrl} />
    </main>
  );
}
